with src as (select *, upper(country) as country_upper from suppliers where rating between 3.2 and 4.1 or country not in ('UK', 'JP')), Summary as (select case when rating >= 3.9 then 'high' when rating >= 2.5 then 'mid' else 'low' end as rating_bucket, count(distinct rating) as unique_countrys, avg(rating) as avg_rating from src group by case when rating >= 3.9 then 'high' when rating >= 2.5 then 'mid' else 'low' end) select rating_bucket, avg_rating from Summary order by avg_rating desc
